<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Area · Nodexa</title><style>:root{--bg:#07111c;--s:#0b1825;--s2:#0f2132;--line:#1b3449;--blue:#3b8cff;--text:#edf6ff;--muted:#7e96aa;--green:#42e9a6;--orange:#ffbd59}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}a{text-decoration:none;color:inherit}.top{height:64px;background:#081522;border-bottom:1px solid var(--line)}.inner{max-width:1320px;height:100%;margin:auto;padding:0 22px;display:flex;align-items:center;justify-content:space-between}.brand{font-size:21px;font-weight:850}.brand b{color:var(--blue)}.user{display:flex;gap:15px;color:#9db0c0;font-size:11px}.nav{background:#0c1b29;border-bottom:1px solid var(--line)}.navin{max-width:1320px;margin:auto;padding:0 15px;display:flex;overflow:auto}.nav a{padding:12px 14px;color:#91a7b8;font-size:11px;border-bottom:2px solid transparent;white-space:nowrap}.nav a:hover,.nav .active{color:#fff;border-color:var(--blue);background:#10273a}.hero{border-bottom:1px solid var(--line);background:#0a1927}.hero>div{max-width:1320px;margin:auto;padding:22px}.hero h1{margin:0 0 4px;font-size:22px}.muted,.small{color:var(--muted);font-size:11px}.wrap{max-width:1320px;margin:18px auto;padding:0 22px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.stat,.card{background:var(--s);border:1px solid var(--line);border-radius:7px}.stat{padding:15px}.stat strong{font-size:22px;display:block}.stat span{font-size:10px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{overflow:hidden;margin-bottom:16px}.title{padding:12px 14px;background:#0d1d2c;border-bottom:1px solid var(--line);font-size:12px;font-weight:750}.row{padding:13px 14px;border-top:1px solid #142a3d;display:flex;align-items:center;justify-content:space-between;gap:10px}.row:first-of-