vices->count()}}</strong><span>Aktive services</span></div><div class="stat"><strong>{{$vpsServices->count()}}</strong><span>VPS'er</span></div><div class="stat"><strong>{{$invoices->where('status','unpaid')->count()}}</strong><span>Ubetalte fakturaer</span></div><div class="stat"><strong>{{$tickets->where('status','!=','closed')->count()}}</strong><span>Åbne tickets</span></div></div><div class="grid"><div><section class="card" id="services"><div class="title">Mine services</div>@forelse($services as $s)<div class="row"><div><strong>{{$s->name??('Server #'.$s->id)}}</strong><div class="small">Spilserver · #{{$s->id}}</div></div><a class="btn" href="/">Administrér</a></div>@empty<div class="empty">Du har ingen aktive spilservere.<br><br><a class="btn" href="/store/games">Bestil service</a></div>@endforelse</section><section class="card" id="vps"><div class="title">Mine VPS'er</div>@forelse($vpsServices as $v)<a href="/client/vps/{{$v->id}}" class="row vpsrow"><div class="vpsinfo"><strong>{{$v->hostname?:('VPS #'.$v->id)}}</strong><div class="small">{{$v->ip_address?:'Afventer IP'}} · OS ID {{$v->os_id?:'—'}} · Flax #{{$v->provider_server_id?:'—'}}</div></div><div class="manage"><span class="status {{$v->status==='awaiting_payment'?'wait':''}}">{{str_replace('_',' ',$v->status)}}</span><span class="btn">Administrér</span></div></a>@empty<div class="empty">Du har ingen VPS'er.<br><br><a class="btn" href="/store/vps">Bestil VPS</a></div>@endforelse</section><section class="card" id="tickets"><div class="title">Support tickets</div>@forelse($tickets->take(5) as $t)<a class="row" href="/client/tickets/{{$t->id}}"><div><strong>#{{$t->id}} · {{$t->subject}}</strong><div class="small">{{$t->department??'Support'}}</div></div><span class="status {{$t->status==='closed'?'':'wait'}}">{{$t->status}}</span></a>@empty<div class="empty">Du har ingen support tickets.</div>@endforelse</section></div><div><section class="card"><div class="title">Hurtige genveje</div><div class="actions"><a class="action" href="/store">＋ Bestil service</a><a class="action" href="/store/vps">☁ Bestil VPS</a><a class="action" href="#new-ticket">? Opret ticket</a><a class="action" href="/account">⚙ Min konto</a></div></section><section class="card" id="invoices"><div class="title">Seneste fakturaer</div>@forelse($invoices->take(5) as $i)<div class="row"><div><strong>{{$i->number??('Faktura #'.$i->id)}}</strong><div class="small">{{$i->status}}</div></div><strong>{{number_format((float)($i->total??0),2,',','.')}} {{$i->currency??'DKK'}}</strong></div>@empty<div class="empty">Ingen fakturaer fundet.</div>@endforelse</section><section class="card" id="new-ticket"><div class="title">Åbn en support ticket</div><form method="POST" action="/client/tickets" class="body">@csrf<input class="field" name="subject" required placeholder="Emne"><select class="field" name="department"><option value="support">Support</option><option value="billing">Fakturering</option><option value="sales">Salg</option></select><textarea class="field" name="message" required rows="4" placeholder="Hvordan kan vi hjælpe dig?"></textarea><button class="btn">Opret ticket</button></form></section></div></div></div></body></html>